  const triangles=brushTriangles(pair.visible,picked.faceIndex,picked.point,radius,{visible:(t,center)=>{const ndc=center.clone().project(view.camera),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(ndc.x,ndc.y),view.camera);const front=firstOpaque(ray);return front?.object===pair.visible&&front.faceIndex===t;}});
